### UDP Network Transport Layer

```csharp
// Core/Network/UDPTransport.cs
using System;
using System.Collections.Concurrent;
using System.Net;
using System.Net.Sockets;
using System.Threading;
using System.Threading.Tasks;

public class UDPTransport : IDisposable
{
    private readonly UdpClient _udpClient;
    private readonly CancellationTokenSource _cts = new();
    private readonly PacketSequence _packetSequence = new();
    private readonly ConcurrentDictionary<IPAddress, PacketSequence> _clientSequences = new();
    private readonly object _lock = new();

    public event Action<Packet> PacketReceived;
    public event Action<Exception> ErrorOccurred;

    public UDPTransport(int port)
    {
        _udpClient = new UdpClient(port);
        _udpClient.Client.ReceiveTimeout = 100; // 100ms timeout
        _udpClient.Client.ReceiveBufferSize = 65536;
    }

    public async Task StartAsync()
    {
        Task.Run(() => ReceiveLoopAsync(_cts.Token));
    }

    private async Task ReceiveLoopAsync(CancellationToken ct)
    {
        try
        {
            while (!ct.IsCancellationRequested)
            {
                try
                {
                    var result = await _udpClient.ReceiveAsync(ct);
                    var packet = Packet.Deserialize(result.Buffer, result.RemoteEndPoint);
                    ProcessPacket(packet);
                }
                catch (SocketException ex) when (ex.SocketErrorCode == SocketError.TimedOut)
                {
                    // Timeout is expected
                }
                catch (Exception ex)
                {
                    ErrorOccurred?.Invoke(ex);
                }
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on shutdown
        }
    }

    private void ProcessPacket(Packet packet)
    {
        lock (_lock)
        {
            var clientSequence = _clientSequences.GetOrAdd(packet.RemoteEndPoint.Address, _ => new PacketSequence());
            var processed = clientSequence.ProcessPacket(packet);

            if (processed)
            {
                PacketReceived?.Invoke(packet);
            }
        }
    }

    public void SendPacket(Packet packet)
    {
        try
        {
            _udpClient.Send(packet.Serialize(), packet.RemoteEndPoint);
        }
        catch (Exception ex)
        {
            ErrorOccurred?.Invoke(ex);
        }
    }

    public void Dispose()
    {
        _cts.Cancel();
        _udpClient?.Dispose();
        _cts.Dispose();
    }
}

// Core/Network/Packet.cs
public class Packet
{
    public byte[] Data { get; }
    public IPEndPoint RemoteEndPoint { get; }
    public ushort SequenceNumber { get; }
    public long Timestamp { get; }

    public Packet(byte[] data, IPEndPoint remoteEndPoint, ushort sequenceNumber, long timestamp)
    {
        Data = data;
        RemoteEndPoint = remoteEndPoint;
        SequenceNumber = sequenceNumber;
        Timestamp = timestamp;
    }

    public static Packet Deserialize(byte[] buffer, IPEndPoint remoteEndPoint)
    {
        // Header: 4 bytes (sequence) + 8 bytes (timestamp) + 2 bytes (length)
        if (buffer.Length < 14) throw new ArgumentException("Invalid packet format");

        var sequence = BitConverter.ToUInt16(buffer, 0);
        var timestamp = BitConverter.ToInt64(buffer, 2);
        var length = BitConverter.ToUInt16(buffer, 10);

        if (buffer.Length < 14 + length) throw new ArgumentException("Invalid packet length");

        var payload = new byte[length];
        Array.Copy(buffer, 12, payload, 0, length);

        return new Packet(payload, remoteEndPoint, sequence, timestamp);
    }

    public byte[] Serialize()
    {
        var header = new byte[12];
        BitConverter.ToUInt16(header, 0, SequenceNumber);
        BitConverter.ToInt64(header, 2, Timestamp);
        BitConverter.ToUInt16(header, 10, (ushort)Data.Length);

        var result = new byte[header.Length + Data.Length];
        Array.Copy(header, result, header.Length);
        Array.Copy(Data, 0, result, header.Length, Data.Length);

        return result;
    }
}

// Core/Network/PacketSequence.cs
public class PacketSequence
{
    private readonly HashSet<ushort> _received = new();
    private readonly object _lock = new();
    private ushort _nextExpected = 0;

    public bool ProcessPacket(Packet packet)
    {
        lock (_lock)
        {
            if (packet.SequenceNumber < _nextExpected)
            {
                // Out of order, buffer it
                _received.Add(packet.SequenceNumber);
                return false;
            }

            // Process all buffered packets before this one
            while (_received.Contains(_nextExpected))
            {
                _received.Remove(_nextExpected);
                _nextExpected++;
            }

            if (packet.SequenceNumber == _nextExpected)
            {
                _nextExpected++;
                return true;
            }

            _received.Add(packet.SequenceNumber);
            return false;
        }
    }
}
