### State Synchronization Engine

```csharp
// Core/State/GameState.cs
public class GameState
{
    private readonly GameWorld _world;
    private readonly StateReplicator _replicator;
    private readonly object _lock = new();
    private long _currentTick = 0;
    private readonly List<StateTick> _ticks = new();
    private readonly int _maxTicksToKeep = 100;

    public GameState(GameWorld world)
    {
        _world = world;
        _replicator = new StateReplicator(this);
    }

    public void Update(float deltaTime)
    {
        lock (_lock)
        {
            _currentTick++;
            var tick = new StateTick(_currentTick, _world.GetSnapshot());
            _ticks.Add(tick);

            if (_ticks.Count > _maxTicksToKeep)
            {
                _ticks.RemoveAt(0);
            }
        }
    }

    public StateTick GetTick(long tickNumber)
    {
        lock (_lock)
        {
            if (tickNumber < _currentTick - _maxTicksToKeep)
            {
                return null;
            }

            var index = (int)(tickNumber - (_currentTick - _maxTicksToKeep));
            return _ticks[index];
        }
    }

    public StateReplicator Replicator => _replicator;
}

// Core/State/StateTick.cs
public class StateTick
{
