        TickNumber = tickNumber;
        Snapshot = snapshot;
    }
}

// Core/State/StateReplicator.cs
public class StateReplicator
{
    private readonly GameState _gameState;
    private readonly object _lock = new();
    private readonly Dictionary<IPAddress, long> _clientTickLags = new();

    public StateReplicator(GameState gameState)
    {
        _gameState = gameState;
    }

    public void SendStateToClient(IPAddress clientAddress, long clientTick)
    {
        lock (_lock)
        {
            var currentTick = _gameState.GetCurrentTick();
            var lag = currentTick - clientTick;

            // Calculate how many ticks to send (with some lookahead)
            var ticksToSend = Math.Min(5, (int)(lag + 2));

            for (int i = 0; i < ticksToSend; i++)
            {
                var tickNumber = currentTick - i;
                var tick = _gameState.GetTick(tickNumber);

                if (tick != null)
                {
                    var packet = new GameStatePacket
                    {
                        TickNumber = tickNumber,
                        Snapshot = tick.Snapshot
                    };

                    // In a real implementation, we'd send this via the UDPTransport
                    // UDPTransport.SendPacket(packet.Serialize());
                }
            }

            _clientTickLags[clientAddress] = lag;
        }
    }

    public long GetClientTickLag(IPAddress clientAddress)
    {
        lock (_lock)
        {
            return _clientTickLags.TryGetValue(clientAddress, out var lag) ? lag : 0;
        }
    }
}
