### Server Integration

```csharp
// Server/Server.cs
public class GameServer : IDisposable
{
    private readonly UDPTransport _transport;
    private readonly GameWorld _world;
    private readonly GameState _gameState;
    private readonly LagCompensation _lagCompensation;
    private readonly PacketHandler _packetHandler;
    private readonly CancellationTokenSource _cts = new();
    private readonly object _lock = new();
    private readonly Dictionary<IPAddress, ClientConnection> _clients = new();

    public GameServer(int port, GameWorld world)
    {
        _transport = new UDPTransport(port);
        _world = world;
        _gameState = new GameState(world);
        _lagCompensation = new LagCompensation(world);
        _packetHandler = new PacketHandler(this);

        _transport.PacketReceived += OnPacketReceived;
        _transport.ErrorOccurred += OnErrorOccurred;
    }

    public async Task StartAsync()
    {
        await _transport.StartAsync();
        Task.Run(() => GameLoop(_cts.Token));
    }

    private async Task GameLoop(CancellationToken ct)
    {
        var lastTime = Stopwatch.GetTimestamp();
        var frameTime = TimeSpan.FromSeconds(1.0 / 60.0);

        while (!ct.IsCancellationRequested)
        {
            var currentTime = Stopwatch.GetTimestamp();
            var deltaTime = TimeSpan.FromTicks(currentTime - lastTime);
            lastTime = currentTime;

            if (deltaTime < frameTime)
            {
                await Task.Delay(frameTime - deltaTime, ct);
                continue;
            }

            lock (_lock)
            {
                _world.Update(deltaTime.TotalSeconds);
                _gameState.Update(deltaTime.TotalSeconds);

                // Send state updates to all clients
                foreach (var client in _clients.Values)
                {
                    _gameState.Replicator.SendStateToClient(client.Address, client.LastReceivedTick);
                }

                // Apply lag compensation
                foreach (var client in _clients.Values)
                {
                    _lagCompensation.ApplyCorrection(client.Address, _gameState.GetCurrentTick());
                }
            }
        }
    }

    private void OnPacketReceived(Packet packet)
    {
        lock (_lock)
        {
            var client = _clients.GetOrAdd(packet.RemoteEndPoint.Address, _ => new ClientConnection(packet.RemoteEndPoint.Address));

            _packetHandler.HandlePacket(packet, client);
        }
    }

    private void OnErrorOccurred(Exception ex)
    {
        Console.Error.WriteLine($"Network error: {ex.Message}");
    }

    public void RegisterClient(IPAddress address)
    {
        lock (_lock)
        {
            _clients[address] = new ClientConnection(address);
            _lagCompensation.RegisterClient(address);
        }
    }

    public void Dispose()
    {
        _cts.Cancel();
        _transport.Dispose();
        _cts.Dispose();
    }
}

// Server/PacketHandler.cs
public class PacketHandler
{
    private readonly GameServer _server;

    public PacketHandler(GameServer server)
    {
        _server = server;
    }

    public void HandlePacket(Packet packet, ClientConnection client)
    {
        try
        {
            var message = GameMessage.Deserialize(packet.Data);

            switch (message.Type)
            {
                case GameMessageType.PlayerInput:
                    var input = (PlayerInputMessage)message;
                    _server._world.ApplyInput(client.Address, input.Input, packet.SequenceNumber);
                    _server._lagCompensation.ProcessInput(client.Address, input.Input);
                    break;

                case GameMessageType.ClientJoin:
                    _server.RegisterClient(packet.RemoteEndPoint.Address);
                    break;

                // Handle other message types
            }
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Error handling packet: {ex.Message}");
        }
    }
}

